def validate_analysis_source(source):
    """Defense-in-depth trusted-source dependency guard, not a Python sandbox."""
    demand(type(source) is str, "SourcePolicy", "source.type", "Policy")
    try:
        tree = ast.parse(source)
    except SyntaxError as error:
        raise LayoutError("SourcePolicy", "source.syntax", "Policy") from error
    forbidden = {"encode_instruction", "decode_instruction", "_FORM_SHAPES", "FULL_OPCODES",
                 "Cpu", "CPU", "Bus", "eval", "exec", "compile", "__import__", "globals",
                 "locals", "vars", "getattr", "setattr", "delattr", "open", "bytes",
                 "bytearray", "memoryview", "input", "print", "help", "breakpoint"}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            demand(all(n.name == "json" and n.asname is None for n in node.names),
                   "SourcePolicy", "source.import", "Policy")
        if isinstance(node, ast.ImportFrom):
            raise LayoutError("SourcePolicy", "source.fromImport", "Policy")
        if isinstance(node, ast.Name):
            demand(node.id not in forbidden, "SourcePolicy", "source.forbiddenName", "Policy")
        if isinstance(node, ast.Constant):
            demand(type(node.value) is not bytes, "SourcePolicy", "source.bytesLiteral", "Policy")
        if isinstance(node, (ast.BitAnd, ast.Mod)):
            raise LayoutError("SourcePolicy", "source.byteMaskOrModulo", "Policy")
        if isinstance(node, ast.Attribute):
            demand(not node.attr.startswith("__") and node.attr not in forbidden | {
                "read_text", "read_bytes", "write_text", "write_bytes", "open", "unlink", "rename",
                "mkdir", "rmdir", "system", "popen", "run", "spawn", "to_bytes", "from_bytes"},
                "SourcePolicy", "source.forbiddenAttribute", "Policy")
    return {"passed": True, "classification": "StaticDependencyGuardNotSandbox",
            "codecCalls": 0, "CPUExecutions": 0, "targetBytes": 0}


def validate_contract(contract, upstream):
    """Pinned fields cannot grant execution; actual math scenarios are computed."""
    expect(contract, PROFILE, "Contract", "contract.completeClosedProfile", "Policy")
    geometry = original_geometry(upstream)
    expect(geometry, {"instructionSites": 18, "instructionLengthSum": 45,
        "blockLengths": {"Common": 16, "NotBelow": 23, "Below": 6},
        "originalOuterEnvelope": 86, "originalExcludedRegion": 41},
        "Contract", "contract.computedGeometry", "Policy")
    sites = reviewed_inventory(upstream)
    computed_edges = []
    for pc, site in sites.items():
        for index, successor in enumerate(site["successors"]):
            kind = ("AnalyticalTerminal" if successor in (0x5596, 0x55C5) else
                    "ConditionalTaken" if site["branch"] is not None and index == 0 else "Fallthrough")
            computed_edges.append({"from": pc, "to": successor, "kind": kind,
                                   "predicate": site["branch"]["predicate"] if site["branch"] is not None else None})
    expect(computed_edges, contract["cfg"]["edges"], "Contract", "contract.computedEdges", "Policy")
    computed_scenarios = []
    for declared in contract["supportedScenarios"]:
        if "request" in declared:
            try:
                result = evaluate_layout(upstream, declared["request"])
            except LayoutError as error:
                demand(declared.get("expectedErrorStage") == error.stage and
                       error.code == ("Rel8OutOfRange" if error.stage == "Branch" else "FallthroughMismatch"),
                       "Contract", declared["id"] + ".expectedRealRefusal", "Policy")
                computed_scenarios.append({"id": declared["id"], "accepted": False,
                    "errorCode": error.code, "errorStage": error.stage})
            else:
                demand("expectedErrorStage" not in declared, "Contract", declared["id"] + ".unexpectedAcceptance", "Policy")
                delta = next(edge["signedDelta"] for edge in result["edges"]
                             if edge["source"] == 0x557D and edge["kind"] == "ConditionalTaken")
                expect(delta, declared["expectedJLTDelta"], "Contract", declared["id"] + ".signedDelta", "Policy")
                if "expectedNotBelowTerminalHazard" in declared:
                    expect(result["terminalMarkers"][0]["hazard"], declared["expectedNotBelowTerminalHazard"],
                           "Contract", declared["id"] + ".terminalHazard", "Policy")
                demand(result["executionBlocked"] is True and result["runtimePermission"] is False,
                       "Contract", declared["id"] + ".nativeBoundary", "Policy")
                computed_scenarios.append({"id": declared["id"], "accepted": True, "JLTDelta": delta,
                    "executionBlocked": True, "nativeExitIsolation": "NativeExitIsolationNotEstablished"})
        elif declared["id"] == "D_RelocatedBases":
            for base in declared["bases"]:
                request = {"syntheticBase": base, "blockOrder": ["Common", "NotBelow", "Below"],
                    "gaps": declared["gaps"], "siteAssignments": None, "classification": "InventedOnlySymbolicLayout"}
                result = evaluate_layout(upstream, request)
                distances = [e["signedDelta"] for e in result["edges"] if e["kind"] == "ConditionalTaken"]
                expect(distances, [23, 10, 7], "Contract", "D_RelocatedBases.relative", "Policy")
                computed_scenarios.append({"id": declared["id"], "base": base, "accepted": True,
                    "distances": distances, "executionBlocked": True})
        else:
            # Independent tests exhaust the wider scalar domain; these actual
            # controls verify the declared near-FFFF policies without a new form.
            span = instruction_span(65535, 1)
            expect(span["endExclusive"], 65536, "Contract", "E.analyticalEndOnly", "Policy")
            for start, length, target, wanted in ((65534, 2, 65535, "BranchNextOutsideProfile"),
                                                 (4096, 2, 65536, "TargetInvalid")):
                try:
                    branch_geometry(start, length, target)
                except LayoutError as error:
                    expect(error.code, wanted, "Contract", "E.noWrapRefusal", "Policy")
                else:
                    raise LayoutError("Contract", "E.noWrapAccepted", "Policy")
            computed_scenarios.append({"id": declared["id"], "accepted": True, "scope": "StandaloneGeometryControlsOnly"})
    return {"passed": True, "milestone": "M2be", "status": "M2be Synthetic Layout/Branch Feasibility Established",
            "classification": "InventedOnlySymbolicLayoutSpecification", "geometry": geometry,
            "edgeCount": len(computed_edges), "computedScenarios": computed_scenarios,
            "nativeExitIsolation": "NativeExitIsolationNotEstablished",
            "physicalROMPlacement": "PhysicalROMPlacementNotEstablished",
            "targetProgramEquivalence": "TargetProgramEquivalenceNotEstablished",
            "firmwareIntegration": "FirmwareIntegrationNotEstablished",
            "executionBlocked": True, "runtimePermission": False, "actualROMExecutions": 0,
            "targetBytes": 0, "encoderCalls": 0, "decoderCalls": 0, "firmwareBin": 0}


def _duplicate_safe(pairs):
    result = {}
    for key, value in pairs:
        demand(key not in result, "RequestShape", "duplicateJSONKey", "Input")
        result[key] = value
    return result


def load_inputs():
    """Only fixed own metadata files, no external-file/ROM arguments."""
    directory = Path(__file__).resolve().parent
    for binding in PROFILE["upstreamBindings"]:
        path = directory.parents[1] / binding["file"]
        data = path.read_bytes()
        demand(len(data) == binding["bytes"] and hashlib.sha256(data).hexdigest() == binding["sha256"],
               "SourceIdentity", binding["file"], "Inventory")
    guard = validate_analysis_source((directory / "layout_feasibility_analysis.py").read_text(encoding="utf-8"))
    raw = (directory / "layout_feasibility_contract.json").read_bytes()
    contract = json.loads(raw, object_pairs_hook=_duplicate_safe)
    expect(raw, (json.dumps(contract, indent=2, ensure_ascii=True) + "\n").encode("utf-8"),
           "Contract", "canonicalContract", "Policy")
    upstream = json.loads((directory / "typed_lowering_contract.json").read_text(encoding="utf-8"), object_pairs_hook=_duplicate_safe)
    return contract, upstream, guard


if __name__ == "__main__":
    demand(len(sys.argv) == 1, "SourcePolicy", "noExternalFileOrROMArguments", "Policy")
    contract, upstream, guard = load_inputs()
    result = validate_contract(contract, upstream)
    result["sourceGuard"] = guard
    result["immutableUpstreamBindings"] = len(PROFILE["upstreamBindings"])
    print(json.dumps(result, sort_keys=True))
